"""Builds synthetic Claude Code transcripts for measuring active time.

Everything is invented. The CANARY-* strings are planted in prompts, tool
input and output, and paths; none of them may leave the reporter. Every line
has a ``uuid``, as Claude Code writes them.

:func:`build` writes the conformance home (``tests/fixtures/active_time/home``,
regenerated by ``make_fixtures.py``). The expected seconds, worked out by hand,
are in the comments and in ``tests/test_active_time.py``.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

CANARY_PROMPT = "CANARY-PROMPT-5c1e"
CANARY_OUTPUT = "CANARY-TOOL-OUTPUT-9d07"
CANARY_PATH = "CANARY-PATH-7f3a"

SESSION = "a7a7a7a7-0000-4000-8000-000000000001"
CWD = f"/work/{CANARY_PATH}/app"
SONNET = "claude-sonnet-4-5"
HAIKU = "claude-haiku-4-5"


def projects_dir(home: Path) -> Path:
    return home / ".claude" / "projects" / f"-work-{CANARY_PATH}-app"


class Transcript:
    """The lines of one transcript: a session's main thread, or one subagent (``agent``)."""

    def __init__(self, session: str, *, agent: str | None = None, model: str = SONNET) -> None:
        self.session = session
        self.agent = agent
        self.model = model
        self.lines: list[dict[str, Any]] = []

    def _base(self, kind: str, when: str) -> dict[str, Any]:
        number = len(self.lines) + 1
        line: dict[str, Any] = {
            "type": kind,
            "uuid": f"{self.session[:8]}-{self.agent or 'main'}-{number:04d}",
            "isSidechain": self.agent is not None,
            "sessionId": self.session,
            "cwd": CWD,
            "gitBranch": "main",
            "version": "2.1.0",
            "timestamp": when,
        }
        if self.agent is not None:
            line["agentId"] = self.agent
        return line

    def prompt(self, when: str, *, origin: str | None = None, meta: bool = False, text: str = "") -> Transcript:
        line = {**self._base("user", when), "message": {"role": "user", "content": text or f"Go on {CANARY_PROMPT}"}}
        if origin is not None:
            line["origin"] = {"kind": origin}
        if meta:
            line["isMeta"] = True
        self.lines.append(line)
        return self

    def answer(
        self,
        when: str,
        *,
        model: str | None = None,
        tokens: int = 100,
        tool: str | None = None,
        call: str | None = None,
        arguments: dict[str, Any] | None = None,
        message: str | None = None,
    ) -> Transcript:
        """An assistant line with usage; with *tool*, it calls that tool (id *call*)."""
        block: dict[str, Any]
        if tool is not None:
            block = {"type": "tool_use", "id": call, "name": tool, "input": arguments or {"command": CANARY_PROMPT}}
        else:
            block = {"type": "text", "text": f"Done. {CANARY_OUTPUT}"}
        number = len(self.lines) + 1
        tag = message or f"{self.session[:4]}{self.agent or 'main'}{number}"
        body = {
            "role": "assistant",
            "model": model or self.model,
            "id": f"msg_{tag}",
            "content": [block],
            "usage": {"input_tokens": tokens, "output_tokens": tokens // 10},
        }
        self.lines.append({**self._base("assistant", when), "message": body, "requestId": f"req_{tag}"})
        return self

    def result(
        self,
        when: str,
        call: str,
        *,
        source: str | None = "config",
        decision: str = "accept",
        denial: str | None = None,
        launched: dict[str, Any] | None = None,
    ) -> Transcript:
        """The tool_result of *call*; *source* is the permission decision's source (``None``: none logged)."""
        block = {"type": "tool_result", "tool_use_id": call, "content": f"output {CANARY_OUTPUT}"}
        line: dict[str, Any] = {**self._base("user", when), "message": {"role": "user", "content": [block]}}
        if source is not None:
            line["permissionDecision"] = {"decision": decision, "source": source}
        if denial is not None:
            line["toolDenialKind"] = denial
        line["toolUseResult"] = launched if launched is not None else {"stdout": CANARY_OUTPUT}
        self.lines.append(line)
        return self

    def turn_end(self, when: str, duration_ms: int = 999_999_999) -> Transcript:
        # durationMs is deliberately absurd: the definition must never read it.
        line = {**self._base("system", when), "subtype": "turn_duration", "durationMs": duration_ms, "isMeta": False}
        self.lines.append(line)
        return self

    def raw(self, line: dict[str, Any]) -> Transcript:
        self.lines.append(line)
        return self

    def path(self, home: Path) -> Path:
        folder = projects_dir(home)
        if self.agent is None:
            return folder / f"{self.session}.jsonl"
        return folder / self.session / "subagents" / f"agent-{self.agent}.jsonl"

    def write(self, home: Path) -> Path:
        target = self.path(home)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text("".join(json.dumps(line) + "\n" for line in self.lines), encoding="utf-8")
        return target


def main_thread() -> Transcript:
    """The main thread: 391 s in the first turn, 46 s in the second, 437 s in all (sonnet).

    Turn 1: prompt 08:00:00 -> answer 08:00:10 (10 s gap); a 6 minute test run 08:00:10..08:06:10 (360 s);
    08:06:10 -> 08:06:20 (10); an async subagent launch 08:06:20..08:06:21 (1); 08:06:21 -> 08:06:30 (9);
    08:06:30 -> turn_end 08:06:31 (1). Total 391.
    Waiting for the subagent's hand-back (08:06:31 -> 08:20:00) is between turns: nothing.
    Turn 2 (the hand-back, an isMeta line with an origin): 08:20:00 -> 08:20:05 (5); an AskUserQuestion
    08:20:05..11:20:05 (3 h of a person answering: nothing); 11:20:05 -> 11:20:10 (5); a hand-approved
    Bash 11:20:10..11:20:40 (30, by the gap rule); 11:20:40 -> 11:20:45 (5); -> turn_end 11:20:46 (1). Total 46.
    """
    main = Transcript(SESSION)
    main.prompt("2026-11-05T08:00:00.000Z", origin="human")
    main.answer("2026-11-05T08:00:10.000Z", tool="Bash", call="toolu_test")
    main.result("2026-11-05T08:06:10.000Z", "toolu_test")
    main.answer("2026-11-05T08:06:20.000Z", tool="Agent", call="toolu_agent1", arguments={"prompt": CANARY_PROMPT})
    main.result("2026-11-05T08:06:21.000Z", "toolu_agent1", launched={"status": "async_launched", "isAsync": True})
    main.answer("2026-11-05T08:06:30.000Z")
    main.turn_end("2026-11-05T08:06:31.000Z")
    main.prompt("2026-11-05T08:20:00.000Z", origin="peer", meta=True)
    main.answer("2026-11-05T08:20:05.000Z", tool="AskUserQuestion", call="toolu_ask")
    main.result("2026-11-05T11:20:05.000Z", "toolu_ask", source="user_temporary")
    main.answer("2026-11-05T11:20:10.000Z", tool="Bash", call="toolu_approved")
    main.result("2026-11-05T11:20:40.000Z", "toolu_approved", source="user_temporary")
    main.answer("2026-11-05T11:20:45.000Z")
    main.turn_end("2026-11-05T11:20:46.000Z")
    return main


def first_subagent() -> Transcript:
    """An async subagent on haiku: 08:06:22 -> 08:06:30 (8), a read 08:06:30..08:06:31 (1),
    08:06:31 -> 08:10:00 (209), 08:10:00 -> 08:25:00 (900 > 600: nothing). Total 218.
    """
    sub = Transcript(SESSION, agent="a1b2c3d4", model=HAIKU)
    sub.prompt("2026-11-05T08:06:22.000Z")
    sub.answer("2026-11-05T08:06:30.000Z", tool="Read", call="toolu_read", arguments={"file_path": f"{CWD}/x.py"})
    sub.result("2026-11-05T08:06:31.000Z", "toolu_read")
    sub.answer("2026-11-05T08:10:00.000Z")
    sub.answer("2026-11-05T08:25:00.000Z")
    return sub


def second_subagent() -> Transcript:
    """A subagent on sonnet: prompt 08:07:00; an isMeta line without an origin at 08:07:30 is no event, so
    08:07:00 -> 08:08:00 counts (60); a coordinator message at 08:09:00 starts a turn (the minute before it
    does not count); 08:09:00 -> 08:09:10 (10). Total 70.
    """
    sub = Transcript(SESSION, agent="e5f6a7b8")
    sub.prompt("2026-11-05T08:07:00.000Z")
    sub.prompt("2026-11-05T08:07:30.000Z", meta=True, text=f"Injected context {CANARY_PROMPT}")
    sub.answer("2026-11-05T08:08:00.000Z")
    sub.prompt("2026-11-05T08:09:00.000Z", origin="coordinator", meta=True)
    sub.answer("2026-11-05T08:09:10.000Z")
    return sub


def build(home: Path) -> Path:
    """The conformance home: one session with its main thread and two subagents."""
    for transcript in (main_thread(), first_subagent(), second_subagent()):
        transcript.write(home)
    return home
